    solution: "trigger OpportunityTrigger on Opportunity (before insert, before update) {\n    for (Opportunity opp : Trigger.new) {\n        Decimal amount = opp.Amount == null ? 0 : opp.Amount;\n        Decimal probability = opp.Probability == null ? 0 : opp.Probability;\n        opp.Weighted_Value__c = (amount * probability / 100).setScale(2);\n\n        if (opp.CloseDate != null) {\n            Integer quarter = ((opp.CloseDate.month() - 1) / 3) + 1;\n            opp.Close_Quarter__c = 'Q' + quarter + ' ' + opp.CloseDate.year();\n        } else {\n            opp.Close_Quarter__c = null;\n        }\n    }\n}\n",
