    title: "Cap line discounts from metadata rules",
    task: "Brightwell Medical Supplies caps discounts by product family and customer tier.\nWrite `OpportunityLineItemTrigger` (before insert, before update) calling `OpportunityLineItemTriggerHandler.enforceDiscountCaps(Trigger.new)`:\n- Rules live in Custom Metadata `Discount_Rule__mdt` (Product_Family__c, Customer_Tier__c, Max_Discount__c)\n- Family = PricebookEntry.Product2.Family; tier = Opportunity.Account.Customer_Tier__c\n- No matching rule → max 10\n- If Discount > max, set Discount = max and Discount_Capped__c = true, else Discount_Capped__c = false\n- Bulk-safe: max 2 SOQL queries, none inside loops",
    starter: "trigger OpportunityLineItemTrigger on OpportunityLineItem (before insert, before update) {\n    // TODO\n}\n\npublic with sharing class OpportunityLineItemTriggerHandler {\n    public static void enforceDiscountCaps(List<OpportunityLineItem> items) {\n        // TODO\n    }\n}\n",
    solution: "trigger OpportunityLineItemTrigger on OpportunityLineItem (before insert, before update) {\n    OpportunityLineItemTriggerHandler.enforceDiscountCaps(Trigger.new);\n}\n\npublic with sharing class OpportunityLineItemTriggerHandler {\n    private static final Decimal DEFAULT_MAX = 10;\n\n    public static void enforceDiscountCaps(List<OpportunityLineItem> items) {\n        Set<Id> pbeIds = new Set<Id>();\n        Set<Id> oppIds = new Set<Id>();\n        for (OpportunityLineItem oli : items) {\n            pbeIds.add(oli.PricebookEntryId);\n            oppIds.add(oli.OpportunityId);\n        }\n        Map<Id, PricebookEntry> entries = new Map<Id, PricebookEntry>([\n            SELECT Id, Product2.Family FROM PricebookEntry WHERE Id IN :pbeIds\n        ]);\n        Map<Id, Opportunity> opps = new Map<Id, Opportunity>([\n            SELECT Id, Account.Customer_Tier__c FROM Opportunity WHERE Id IN :oppIds\n        ]);\n\n        Map<String, Decimal> maxByKey = new Map<String, Decimal>();\n        for (Discount_Rule__mdt rule : Discount_Rule__mdt.getAll().values()) {\n            maxByKey.put(rule.Product_Family__c + '|' + rule.Customer_Tier__c, rule.Max_Discount__c);\n        }\n\n        for (OpportunityLineItem oli : items) {\n            oli.Discount_Capped__c = false;\n            if (oli.Discount == null) {\n                continue;\n            }\n            PricebookEntry pbe = entries.get(oli.PricebookEntryId);\n            Opportunity opp = opps.get(oli.OpportunityId);\n            String family = pbe == null || pbe.Product2 == null ? null : pbe.Product2.Family;\n            String tier = opp == null || opp.Account == null ? null : opp.Account.Customer_Tier__c;\n            Decimal maxDiscount = maxByKey.get(family + '|' + tier);\n            if (maxDiscount == null) {\n                maxDiscount = DEFAULT_MAX;\n            }\n            if (oli.Discount > maxDiscount) {\n                oli.Discount = maxDiscount;\n                oli.Discount_Capped__c = true;\n            }\n        }\n    }\n}\n",
    checks: [{ re: /Discount_Rule__mdt\.getAll\s*\(|Discount_Rule__mdt\.getInstance\s*\(|FROM\s+Discount_Rule__mdt/i, msg: "Reads the Discount_Rule__mdt custom metadata" }, { re: /Product2\.Family/i, msg: "Uses Product2.Family" }, { re: /Account\.Customer_Tier__c/i, msg: "Uses the opportunity's Account.Customer_Tier__c" }, { re: /Discount_Capped__c\s*=\s*true/i, msg: "Flags capped lines" }, { re: /\b10\b/, msg: "Falls back to a maximum of 10 when no rule matches" }],
    forbid: [{ re: /for\s*\([^)]*\)\s*\{[^}]*\[\s*SELECT/i, msg: "No SOQL inside loops" }, { re: /\b(insert|update|delete|upsert)\s+\w+\s*;/i, msg: "No DML needed — change Trigger.new directly in a before trigger" }],
    hints: ["Collect PricebookEntryIds and OpportunityIds first, then query both with relationship fields.", "Build a Map<String, Decimal> keyed by 'family|tier' from Discount_Rule__mdt.getAll().values().", "Guard against a null Account on the opportunity before reading the tier."],
