    id: "TR014",
    track: "triggers",
    level: "Hard",
    topic: "Validation",
    title: "Prevent overlapping room bookings",
    task: "Quayside Co-Working books meeting rooms with custom object Room_Booking__c (Room__c lookup, Start__c, End__c datetimes).\nWrite `RoomBookingTriggerHandler.preventOverlaps(List<Room_Booking__c> bookings)` for before insert/update:\n- End__c must be after Start__c (field error on End__c)\n- A booking clashes when start < other end AND end > other start for the same room\n- Check against existing bookings with ONE query filtered by Room__c IN, the time window (Start__c < :maxEnd AND End__c > :minStart), excluding the batch's own Ids\n- Also check clashes inside the batch: the first booking wins, later ones get a record error",
    starter: "public with sharing class RoomBookingTriggerHandler {\n    public static void preventOverlaps(List<Room_Booking__c> bookings) {\n        // TODO\n    }\n}\n",
    solution: "public with sharing class RoomBookingTriggerHandler {\n    public static void preventOverlaps(List<Room_Booking__c> bookings) {\n        Set<Id> roomIds = new Set<Id>();\n        Set<Id> batchIds = new Set<Id>();\n        Datetime minStart;\n        Datetime maxEnd;\n        List<Room_Booking__c> toCheck = new List<Room_Booking__c>();\n        for (Room_Booking__c b : bookings) {\n            if (b.Id != null) {\n                batchIds.add(b.Id);\n            }\n            if (b.Room__c == null || b.Start__c == null || b.End__c == null) {\n                continue;\n            }\n            if (b.End__c <= b.Start__c) {\n                b.End__c.addError('End must be after start.');\n                continue;\n            }\n            toCheck.add(b);\n            roomIds.add(b.Room__c);\n            if (minStart == null || b.Start__c < minStart) {\n                minStart = b.Start__c;\n            }\n            if (maxEnd == null || b.End__c > maxEnd) {\n                maxEnd = b.End__c;\n            }\n        }\n        if (toCheck.isEmpty()) {\n            return;\n        }\n\n        Map<Id, List<Room_Booking__c>> byRoom = new Map<Id, List<Room_Booking__c>>();\n        for (Room_Booking__c existing : [\n            SELECT Id, Room__c, Start__c, End__c FROM Room_Booking__c\n            WHERE Room__c IN :roomIds AND Start__c < :maxEnd AND End__c > :minStart\n            AND Id NOT IN :batchIds\n        ]) {\n            addToRoom(byRoom, existing);\n        }\n\n        for (Room_Booking__c b : toCheck) {\n            Boolean clash = false;\n            List<Room_Booking__c> sameRoom = byRoom.get(b.Room__c);\n            if (sameRoom != null) {\n                for (Room_Booking__c other : sameRoom) {\n                    if (b.Start__c < other.End__c && b.End__c > other.Start__c) {\n                        clash = true;\n                        break;\n                    }\n                }\n            }\n            if (clash) {\n                b.addError('This room is already booked for an overlapping time.');\n            } else {\n                addToRoom(byRoom, b);\n            }\n        }\n    }\n\n    private static void addToRoom(Map<Id, List<Room_Booking__c>> byRoom, Room_Booking__c booking) {\n        if (!byRoom.containsKey(booking.Room__c)) {\n            byRoom.put(booking.Room__c, new List<Room_Booking__c>());\n        }\n        byRoom.get(booking.Room__c).add(booking);\n    }\n}\n",
    checks: [{ re: /Room__c\s+IN\s*:/i, msg: "Filters existing bookings by Room__c IN" }, { re: /Start__c\s*<\s*:\s*\w+/i, msg: "Filters Start__c < window end in SOQL" }, { re: /End__c\s*>\s*:\s*\w+/i, msg: "Filters End__c > window start in SOQL" }, { re: /NOT\s+IN\s*:/i, msg: "Excludes the batch's own records" }, { re: /\.addError\s*\(/i, msg: "Adds errors to clashing bookings" }],
    forbid: [{ re: /for\s*\([^)]*\)\s*\{[^}]*\[\s*SELECT/i, msg: "No SOQL inside loops" }, { re: /\b(insert|update|delete|upsert)\s+\w+\s*;/i, msg: "No DML needed — change Trigger.new directly in a before trigger" }],
    hints: ["Compute the earliest start and latest end in the batch to bound the query.", "Group existing bookings by room, then compare each incoming booking with that list.", "Add a booking to the room list after it passes, so later bookings in the batch are checked against it."],
