    solution: "public with sharing class PurchaseOrderTriggerHandler {\n    private static final Map<String, Set<String>> ALLOWED = new Map<String, Set<String>>{\n        'Draft' => new Set<String>{ 'Submitted' },\n        'Submitted' => new Set<String>{ 'Approved', 'Rejected' },\n        'Approved' => new Set<String>{ 'Ordered' },\n        'Rejected' => new Set<String>{ 'Draft' },\n        'Ordered' => new Set<String>{ 'Received' },\n        'Received' => new Set<String>()\n    };\n\n    public static void enforceStatusFlow(List<Purchase_Order__c> newList, Map<Id, Purchase_Order__c> oldMap) {\n        for (Purchase_Order__c po : newList) {\n            String oldStatus = oldMap.get(po.Id).Status__c;\n            String newStatus = po.Status__c;\n            if (newStatus == oldStatus) {\n                continue;\n            }\n            Set<String> nextAllowed = ALLOWED.get(oldStatus);\n            if (nextAllowed == null || !nextAllowed.contains(newStatus)) {\n                po.Status__c.addError('Status cannot move from ' + oldStatus + ' to ' + newStatus + '.');\n            } else if (newStatus == 'Approved') {\n                po.Approved_By__c = UserInfo.getUserId();\n                po.Approved_On__c = Date.today();\n            }\n        }\n    }\n}\n",
