    solution: "public with sharing class ContactTriggerHandler {\n    private static final List<Schema.SObjectField> ADDRESS_FIELDS = new List<Schema.SObjectField>{\n        Contact.MailingStreet, Contact.MailingCity, Contact.MailingPostalCode, Contact.MailingCountry\n    };\n\n    public static void resetVerificationOnAddressChange(List<Contact> newList, Map<Id, Contact> oldMap) {\n        for (Contact c : newList) {\n            if (hasChanged(c, oldMap.get(c.Id), ADDRESS_FIELDS)) {\n                c.Address_Verified__c = false;\n                c.Address_Last_Changed__c = Datetime.now();\n            }\n        }\n    }\n\n    private static Boolean hasChanged(SObject newRecord, SObject oldRecord, List<Schema.SObjectField> fields) {\n        if (oldRecord == null) {\n            return true;\n        }\n        for (Schema.SObjectField field : fields) {\n            if (newRecord.get(field) != oldRecord.get(field)) {\n                return true;\n            }\n        }\n        return false;\n    }\n}\n",
