    solution: "trigger InvoiceTrigger on Invoice__c (after insert, after update, after delete, after undelete) {\n    InvoiceRollupHandler.handle(Trigger.new, Trigger.oldMap);\n}\n\npublic with sharing class InvoiceRollupHandler {\n    public static void handle(List<Invoice__c> newList, Map<Id, Invoice__c> oldMap) {\n        Set<Id> accountIds = new Set<Id>();\n        if (newList == null) {\n            for (Invoice__c inv : oldMap.values()) {\n                accountIds.add(inv.Account__c);\n            }\n        } else {\n            for (Invoice__c inv : newList) {\n                Invoice__c oldInv = oldMap == null ? null : oldMap.get(inv.Id);\n                if (oldInv == null) {\n                    accountIds.add(inv.Account__c);\n                } else if (inv.Account__c != oldInv.Account__c\n                        || inv.Balance__c != oldInv.Balance__c\n                        || inv.Status__c != oldInv.Status__c) {\n                    accountIds.add(inv.Account__c);\n                    accountIds.add(oldInv.Account__c);\n                }\n            }\n        }\n        accountIds.remove(null);\n        if (accountIds.isEmpty()) {\n            return;\n        }\n\n        Map<Id, Account> updates = new Map<Id, Account>();\n        for (Id accId : accountIds) {\n            updates.put(accId, new Account(Id = accId, Outstanding_Balance__c = 0));\n        }\n        for (AggregateResult ar : [\n            SELECT Account__c accId, SUM(Balance__c) outstanding FROM Invoice__c\n            WHERE Account__c IN :accountIds AND Status__c != 'Paid'\n            GROUP BY Account__c\n        ]) {\n            Decimal outstanding = (Decimal) ar.get('outstanding');\n            updates.get((Id) ar.get('accId')).Outstanding_Balance__c = outstanding == null ? 0 : outstanding;\n        }\n        update updates.values();\n    }\n}\n",
