    solution: "trigger TaskTrigger on Task (after insert, after update, after delete, after undelete) {\n    TaskRollupHandler.handle(Trigger.new, Trigger.oldMap);\n}\n\npublic with sharing class TaskRollupHandler {\n    public static void handle(List<Task> newList, Map<Id, Task> oldMap) {\n        Set<Id> caseIds = new Set<Id>();\n        if (newList != null) {\n            for (Task t : newList) {\n                addIfCase(caseIds, t.WhatId);\n            }\n        }\n        if (oldMap != null) {\n            for (Task t : oldMap.values()) {\n                addIfCase(caseIds, t.WhatId);\n            }\n        }\n        if (caseIds.isEmpty()) {\n            return;\n        }\n\n        Map<Id, Case> updates = new Map<Id, Case>();\n        for (Id caseId : caseIds) {\n            updates.put(caseId, new Case(Id = caseId, Open_Task_Count__c = 0));\n        }\n        for (AggregateResult ar : [\n            SELECT WhatId caseId, COUNT(Id) openCount FROM Task\n            WHERE WhatId IN :caseIds AND IsClosed = false\n            GROUP BY WhatId\n        ]) {\n            updates.get((Id) ar.get('caseId')).Open_Task_Count__c = (Integer) ar.get('openCount');\n        }\n        update updates.values();\n    }\n\n    private static void addIfCase(Set<Id> caseIds, Id whatId) {\n        if (whatId != null && whatId.getSObjectType() == Case.SObjectType) {\n            caseIds.add(whatId);\n        }\n    }\n}\n",
