    solution: "public with sharing class OpportunityTriggerHandler {\n    public static void createProjects(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {\n        Set<Id> wonIds = new Set<Id>();\n        for (Opportunity opp : newList) {\n            if (opp.IsWon && !oldMap.get(opp.Id).IsWon) {\n                wonIds.add(opp.Id);\n            }\n        }\n        if (wonIds.isEmpty()) {\n            return;\n        }\n\n        Set<Id> alreadyHasProject = new Set<Id>();\n        for (Project__c p : [SELECT Opportunity__c FROM Project__c WHERE Opportunity__c IN :wonIds]) {\n            alreadyHasProject.add(p.Opportunity__c);\n        }\n\n        List<Project__c> projects = new List<Project__c>();\n        for (Opportunity opp : newList) {\n            if (!wonIds.contains(opp.Id) || alreadyHasProject.contains(opp.Id)) {\n                continue;\n            }\n            projects.add(new Project__c(\n                Name = opp.Name.left(69) + ' - Delivery',\n                Account__c = opp.AccountId,\n                Opportunity__c = opp.Id,\n                Start_Date__c = opp.CloseDate.addDays(14)\n            ));\n        }\n        if (!projects.isEmpty()) {\n            insert projects;\n        }\n    }\n}\n",
