    solution: "public with sharing class RenewalService {\n    public static void createRenewals(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {\n        Map<Id, Opportunity> renewalByOriginal = new Map<Id, Opportunity>();\n        for (Opportunity opp : newList) {\n            Opportunity oldOpp = oldMap.get(opp.Id);\n            if (opp.IsWon && !oldOpp.IsWon && opp.Auto_Renew__c) {\n                renewalByOriginal.put(opp.Id, new Opportunity(\n                    Name = ('Renewal - ' + opp.Name).left(120),\n                    AccountId = opp.AccountId,\n                    OwnerId = opp.OwnerId,\n                    Pricebook2Id = opp.Pricebook2Id,\n                    CloseDate = opp.CloseDate.addMonths(12),\n                    StageName = 'Prospecting',\n                    Type = 'Renewal',\n                    Original_Opportunity__c = opp.Id\n                ));\n            }\n        }\n        if (renewalByOriginal.isEmpty()) {\n            return;\n        }\n        insert renewalByOriginal.values();\n\n        List<OpportunityLineItem> newLines = new List<OpportunityLineItem>();\n        for (OpportunityLineItem line : [\n            SELECT OpportunityId, PricebookEntryId, Quantity, UnitPrice, Discount, Description\n            FROM OpportunityLineItem\n            WHERE OpportunityId IN :renewalByOriginal.keySet()\n        ]) {\n            newLines.add(new OpportunityLineItem(\n                OpportunityId = renewalByOriginal.get(line.OpportunityId).Id,\n                PricebookEntryId = line.PricebookEntryId,\n                Quantity = line.Quantity,\n                UnitPrice = line.UnitPrice,\n                Discount = line.Discount,\n                Description = line.Description\n            ));\n        }\n        if (!newLines.isEmpty()) {\n            insert newLines;\n        }\n    }\n}\n",
    checks: [{ re: /IsWon|'Closed Won'/i, msg: "Detects newly won opportunities" }, { re: /addMonths\s*\(\s*12\s*\)/i, msg: "Sets the renewal close date 12 months later" }, { re: /Original_Opportunity__c\s*=/i, msg: "Links the renewal to the original" }, { re: /FROM\s+OpportunityLineItem/i, msg: "Queries the original line items" }, { re: /PricebookEntryId\s*=|\.clone\s*\(/i, msg: "Copies line items onto the renewal" }],
