    starter: "public with sharing class CaseTriggerHandler {\n    public static void escalateParents(List<Case> newList, Map<Id, Case> oldMap) {\n        // TODO\n    }\n}\n",
    solution: "public with sharing class CaseTriggerHandler {\n    @TestVisible\n    private static Set<Id> escalatedIds = new Set<Id>();\n\n    public static void escalateParents(List<Case> newList, Map<Id, Case> oldMap) {\n        Set<Id> parentIds = new Set<Id>();\n        for (Case c : newList) {\n            Boolean becameHigh = c.Priority == 'High' && oldMap.get(c.Id).Priority != 'High';\n            if (!becameHigh || c.ParentId == null || escalatedIds.contains(c.Id)) {\n                continue;\n            }\n            escalatedIds.add(c.Id);\n            parentIds.add(c.ParentId);\n        }\n        if (parentIds.isEmpty()) {\n            return;\n        }\n\n        List<Case> parents = new List<Case>();\n        for (Case parent : [\n            SELECT Id FROM Case\n            WHERE Id IN :parentIds AND Priority != 'High' AND IsClosed = false\n        ]) {\n            parent.Priority = 'High';\n            parents.add(parent);\n        }\n        if (!parents.isEmpty()) {\n            update parents;\n        }\n    }\n}\n",
