    starter: "public with sharing class AccountContactStatusSync {\n    public static void fromAccounts(List<Account> newList, Map<Id, Account> oldMap) {\n        // TODO\n    }\n\n    public static void fromContacts(List<Contact> newList, Map<Id, Contact> oldMap) {\n        // TODO\n    }\n}\n",
    solution: "public with sharing class AccountContactStatusSync {\n    @TestVisible\n    private static Set<Id> accountsSynced = new Set<Id>();\n    @TestVisible\n    private static Set<Id> contactsSynced = new Set<Id>();\n\n    public static void fromAccounts(List<Account> newList, Map<Id, Account> oldMap) {\n        Map<Id, String> statusByAccount = new Map<Id, String>();\n        for (Account acc : newList) {\n            if (accountsSynced.contains(acc.Id)) {\n                continue;\n            }\n            if (acc.Customer_Status__c != oldMap.get(acc.Id).Customer_Status__c) {\n                statusByAccount.put(acc.Id, acc.Customer_Status__c);\n            }\n        }\n        if (statusByAccount.isEmpty()) {\n            return;\n        }\n        accountsSynced.addAll(statusByAccount.keySet());\n\n        List<Contact> contacts = [\n            SELECT Id, AccountId FROM Contact WHERE AccountId IN :statusByAccount.keySet()\n        ];\n        for (Contact c : contacts) {\n            c.Account_Status__c = statusByAccount.get(c.AccountId);\n            contactsSynced.add(c.Id);\n        }\n        if (!contacts.isEmpty()) {\n            update contacts;\n        }\n    }\n\n    public static void fromContacts(List<Contact> newList, Map<Id, Contact> oldMap) {\n        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();\n        for (Contact c : newList) {\n            if (contactsSynced.contains(c.Id) || c.AccountId == null) {\n                continue;\n            }\n            if (c.Account_Status__c != oldMap.get(c.Id).Account_Status__c) {\n                accountsToUpdate.put(c.AccountId, new Account(\n                    Id = c.AccountId,\n                    Customer_Status__c = c.Account_Status__c\n                ));\n                contactsSynced.add(c.Id);\n            }\n        }\n        if (accountsToUpdate.isEmpty()) {\n            return;\n        }\n        accountsSynced.addAll(accountsToUpdate.keySet());\n        update accountsToUpdate.values();\n    }\n}\n",
