    id: "TR045",
    track: "triggers",
    level: "Medium",
    topic: "Handler pattern",
    title: "Virtual base trigger handler",
    task: "Ashworth Legal LLP wants a reusable handler base.\n- `TriggerHandler` (virtual, inherited sharing): public `run()` that switches on Trigger.operationType and calls protected virtual no-op methods: beforeInsert(List<SObject>), beforeUpdate(List<SObject>, Map<Id, SObject>), afterInsert(List<SObject>), afterUpdate(List<SObject>, Map<Id, SObject>)\n- `ContactTriggerHandler extends TriggerHandler`: override beforeInsert (LeadSource blank → 'Referral') and afterUpdate (when AccountId changes to a non-null account, create a Task on that account, WhoId = contact, Subject 'Contact moved to this account'; one insert)\n- `ContactTrigger`: `new ContactTriggerHandler().run();`",
    starter: "public virtual inherited sharing class TriggerHandler {\n    public void run() {\n        // TODO\n    }\n}\n\npublic with sharing class ContactTriggerHandler extends TriggerHandler {\n    // TODO\n}\n\ntrigger ContactTrigger on Contact (before insert, after update) {\n    // TODO\n}\n",
    solution: "public virtual inherited sharing class TriggerHandler {\n    public void run() {\n        switch on Trigger.operationType {\n            when BEFORE_INSERT {\n                beforeInsert(Trigger.new);\n            }\n            when BEFORE_UPDATE {\n                beforeUpdate(Trigger.new, Trigger.oldMap);\n            }\n            when AFTER_INSERT {\n                afterInsert(Trigger.new);\n            }\n            when AFTER_UPDATE {\n                afterUpdate(Trigger.new, Trigger.oldMap);\n            }\n        }\n    }\n\n    protected virtual void beforeInsert(List<SObject> newList) {}\n    protected virtual void beforeUpdate(List<SObject> newList, Map<Id, SObject> oldMap) {}\n    protected virtual void afterInsert(List<SObject> newList) {}\n    protected virtual void afterUpdate(List<SObject> newList, Map<Id, SObject> oldMap) {}\n}\n\npublic with sharing class ContactTriggerHandler extends TriggerHandler {\n    protected override void beforeInsert(List<SObject> newList) {\n        for (Contact c : (List<Contact>) newList) {\n            if (String.isBlank(c.LeadSource)) {\n                c.LeadSource = 'Referral';\n            }\n        }\n    }\n\n    protected override void afterUpdate(List<SObject> newList, Map<Id, SObject> oldMap) {\n        Map<Id, Contact> oldContacts = (Map<Id, Contact>) oldMap;\n        List<Task> tasks = new List<Task>();\n        for (Contact c : (List<Contact>) newList) {\n            if (c.AccountId != null && c.AccountId != oldContacts.get(c.Id).AccountId) {\n                tasks.add(new Task(\n                    WhatId = c.AccountId,\n                    WhoId = c.Id,\n                    Subject = 'Contact moved to this account'\n                ));\n            }\n        }\n        if (!tasks.isEmpty()) {\n            insert tasks;\n        }\n    }\n}\n\ntrigger ContactTrigger on Contact (before insert, after update) {\n    new ContactTriggerHandler().run();\n}\n",
    checks: [{ re: /switch\s+on\s+Trigger\.operationType/i, msg: "Base run() switches on Trigger.operationType" }, { re: /protected\s+virtual\s+void\s+beforeInsert\s*\(/i, msg: "Declares overridable virtual event methods" }, { re: /override\s+void\s+beforeInsert\s*\(/i, msg: "ContactTriggerHandler overrides beforeInsert" }, { re: /override\s+void\s+afterUpdate\s*\(/i, msg: "ContactTriggerHandler overrides afterUpdate" }, { re: /new\s+ContactTriggerHandler\s*\(\s*\)\s*\.\s*run\s*\(\s*\)/i, msg: "Trigger runs the handler" }],
    forbid: [{ re: /for\s*\([^)]*\)\s*\{[^}]*\b(insert|update|delete|upsert)\s+\w+\s*;/i, msg: "No DML inside loops" }],
