    starter: "public with sharing class TriggerBypass {\n    public static void bypass(String handlerName) {\n        // TODO\n    }\n\n    public static void clearBypass(String handlerName) {\n        // TODO\n    }\n\n    public static Boolean isBypassed(String handlerName) {\n        // TODO\n        return false;\n    }\n}\n\npublic with sharing class MembershipService {\n    public static void renewAll(List<Contact> members) {\n        // TODO\n    }\n}\n\npublic with sharing class ContactTriggerHandler {\n    public static void run() {\n        // TODO: return early when bypassed\n        switch on Trigger.operationType {\n            when BEFORE_UPDATE {\n                for (Contact c : (List<Contact>) Trigger.new) {\n                    c.Manual_Edit__c = true;\n                }\n            }\n        }\n    }\n}\n",
    solution: "public with sharing class TriggerBypass {\n    private static final Set<String> BYPASSED = new Set<String>();\n\n    public static void bypass(String handlerName) {\n        BYPASSED.add(handlerName);\n    }\n\n    public static void clearBypass(String handlerName) {\n        BYPASSED.remove(handlerName);\n    }\n\n    public static Boolean isBypassed(String handlerName) {\n        if (BYPASSED.contains(handlerName)) {\n            return true;\n        }\n        if (FeatureManagement.checkPermission('Bypass_All_Triggers')) {\n            return true;\n        }\n        Bypass_Settings__c settings = Bypass_Settings__c.getInstance();\n        return settings != null && settings.Bypass_All__c == true;\n    }\n}\n\npublic with sharing class MembershipService {\n    public static void renewAll(List<Contact> members) {\n        if (members == null || members.isEmpty()) {\n            return;\n        }\n        for (Contact c : members) {\n            Date base = c.Membership_Expiry__c == null ? Date.today() : c.Membership_Expiry__c;\n            c.Membership_Expiry__c = base.addYears(1);\n        }\n        TriggerBypass.bypass('ContactTriggerHandler');\n        try {\n            update members;\n        } finally {\n            TriggerBypass.clearBypass('ContactTriggerHandler');\n        }\n    }\n}\n\npublic with sharing class ContactTriggerHandler {\n    public static void run() {\n        if (TriggerBypass.isBypassed('ContactTriggerHandler')) {\n            return;\n        }\n        switch on Trigger.operationType {\n            when BEFORE_UPDATE {\n                for (Contact c : (List<Contact>) Trigger.new) {\n                    c.Manual_Edit__c = true;\n                }\n            }\n        }\n    }\n}\n",
