    forbid: [{ re: /static\s+(final\s+)?Boolean\s+\w+\s*(=|;)/i, msg: "Use a set of handler names, not a global Boolean" }, { re: /for\s*\([^)]*\)\s*\{[^}]*\b(insert|update|delete|upsert)\s+\w+\s*;/i, msg: "No DML inside loops" }],
