    id: "TR050",
    track: "triggers",
    level: "Easy",
    topic: "Duplicate prevention",
    title: "Block accounts that already exist",
    task: "Tamar Valley Dairies keeps creating the same farm twice.\nWrite `AccountDuplicateChecker.blockExisting(List<Account> accounts)` called from before insert:\n- An account is a duplicate if an existing Account has the same Name (case-insensitive) AND the same BillingPostalCode ignoring spaces and case (both null counts as equal)\n- Use ONE query: WHERE Name IN :names\n- Duplicates get a record-level error 'An account with this name and postcode already exists.'",
    starter: "public with sharing class AccountDuplicateChecker {\n    public static void blockExisting(List<Account> accounts) {\n        // TODO\n    }\n}\n",
    solution: "public with sharing class AccountDuplicateChecker {\n    public static void blockExisting(List<Account> accounts) {\n        Set<String> names = new Set<String>();\n        for (Account acc : accounts) {\n            if (String.isNotBlank(acc.Name)) {\n                names.add(acc.Name.trim());\n            }\n        }\n        if (names.isEmpty()) {\n            return;\n        }\n\n        Set<String> existingKeys = new Set<String>();\n        for (Account existing : [\n            SELECT Name, BillingPostalCode FROM Account WHERE Name IN :names\n        ]) {\n            existingKeys.add(keyFor(existing));\n        }\n\n        for (Account acc : accounts) {\n            if (String.isNotBlank(acc.Name) && existingKeys.contains(keyFor(acc))) {\n                acc.addError('An account with this name and postcode already exists.');\n            }\n        }\n    }\n\n    private static String keyFor(Account acc) {\n        String postcode = acc.BillingPostalCode == null ? '' : acc.BillingPostalCode.deleteWhitespace();\n        return (acc.Name.trim() + '|' + postcode).toLowerCase();\n    }\n}\n",
