    starter: "public with sharing class AccountDedupeHandler {\n    public static void preventDuplicates(List<Account> newList, Map<Id, Account> oldMap) {\n        // TODO\n    }\n\n    @TestVisible\n    private static String normalise(String name) {\n        // TODO\n        return null;\n    }\n}\n",
    solution: "public with sharing class AccountDedupeHandler {\n    private static final Pattern SUFFIX = Pattern.compile('\\\\b(ltd|limited|plc|llp)\\\\b');\n\n    public static void preventDuplicates(List<Account> newList, Map<Id, Account> oldMap) {\n        Map<String, Account> byKey = new Map<String, Account>();\n        for (Account acc : newList) {\n            acc.Normalised_Name__c = normalise(acc.Name);\n            Account oldAcc = oldMap == null ? null : oldMap.get(acc.Id);\n            Boolean nameChanged = oldAcc == null || oldAcc.Name != acc.Name;\n            if (acc.Allow_Duplicate__c == true) {\n                acc.Allow_Duplicate__c = false;\n                continue;\n            }\n            if (!nameChanged || String.isBlank(acc.Normalised_Name__c)) {\n                continue;\n            }\n            if (byKey.containsKey(acc.Normalised_Name__c)) {\n                acc.Name.addError('Another account in this batch has the same name.');\n            } else {\n                byKey.put(acc.Normalised_Name__c, acc);\n            }\n        }\n        if (byKey.isEmpty()) {\n            return;\n        }\n\n        for (Account existing : [\n            SELECT Id, Name, Normalised_Name__c FROM Account\n            WHERE Normalised_Name__c IN :byKey.keySet()\n        ]) {\n            Account incoming = byKey.get(existing.Normalised_Name__c.toLowerCase());\n            if (incoming != null && incoming.Id != existing.Id) {\n                incoming.Name.addError('Possible duplicate of \"' + existing.Name\n                    + '\". Tick Allow Duplicate to save anyway.');\n            }\n        }\n    }\n\n    @TestVisible\n    private static String normalise(String name) {\n        if (String.isBlank(name)) {\n            return null;\n        }\n        String value = name.toLowerCase().replace('&', ' and ');\n        value = value.replaceAll('[^a-z0-9 ]', ' ');\n        value = SUFFIX.matcher(value).replaceAll(' ');\n        return value.normalizeSpace();\n    }\n}\n",
