    id: "TR055",
    track: "triggers",
    level: "Hard",
    topic: "Duplicate prevention",
    title: "Flag leads via duplicate rules API",
    task: "Penrose Mortgage Brokers wants to reuse its active Duplicate Rules in Apex instead of re-coding matching logic.\nWrite `LeadDuplicateFlagger.flagPossibleDuplicates(List<Lead> leads)` for before insert:\n- Reset Possible_Duplicate__c = false and Duplicate_Record_Id__c = null on every lead\n- Call `Datacloud.FindDuplicates.findDuplicates()` in chunks of at most 50 records (the API limit)\n- For each lead, take the first matched record (DuplicateResult → MatchResult → MatchRecord) and set Possible_Duplicate__c = true and Duplicate_Record_Id__c\n- If the call throws (e.g. no active rule), leave the leads unflagged; never block the insert",
    starter: "public with sharing class LeadDuplicateFlagger {\n    public static void flagPossibleDuplicates(List<Lead> leads) {\n        // TODO\n    }\n}\n",
    solution: "public with sharing class LeadDuplicateFlagger {\n    private static final Integer CHUNK_SIZE = 50;\n\n    public static void flagPossibleDuplicates(List<Lead> leads) {\n        for (Lead l : leads) {\n            l.Possible_Duplicate__c = false;\n            l.Duplicate_Record_Id__c = null;\n        }\n        try {\n            for (Integer start = 0; start < leads.size(); start += CHUNK_SIZE) {\n                List<Lead> chunk = new List<Lead>();\n                Integer stop = Math.min(start + CHUNK_SIZE, leads.size());\n                for (Integer i = start; i < stop; i++) {\n                    chunk.add(leads[i]);\n                }\n                List<Datacloud.FindDuplicatesResult> results = Datacloud.FindDuplicates.findDuplicates(chunk);\n                for (Integer i = 0; i < results.size(); i++) {\n                    Id matchId = firstMatch(results[i]);\n                    if (matchId != null) {\n                        chunk[i].Possible_Duplicate__c = true;\n                        chunk[i].Duplicate_Record_Id__c = matchId;\n                    }\n                }\n            }\n        } catch (Exception e) {\n            // No active duplicate rule (or the service is unavailable): leave leads unflagged\n            System.debug(LoggingLevel.WARN, 'Duplicate check skipped: ' + e.getMessage());\n        }\n    }\n\n    private static Id firstMatch(Datacloud.FindDuplicatesResult result) {\n        for (Datacloud.DuplicateResult dup : result.getDuplicateResults()) {\n            for (Datacloud.MatchResult match : dup.getMatchResults()) {\n                for (Datacloud.MatchRecord rec : match.getMatchRecords()) {\n                    return rec.getRecord().Id;\n                }\n            }\n        }\n        return null;\n    }\n}\n",
    checks: [{ re: /Datacloud\.FindDuplicates\.findDuplicates\s*\(/i, msg: "Calls Datacloud.FindDuplicates.findDuplicates()" }, { re: /\b50\b/, msg: "Chunks the records in groups of 50" }, { re: /getMatchRecords\s*\(\s*\)/i, msg: "Reads the match records" }, { re: /Possible_Duplicate__c\s*=\s*true/i, msg: "Flags matched leads" }, { re: /catch\s*\(/i, msg: "Handles the exception when no rule is active" }],
